"""Dispatch for native gated activation CuTe kernels."""

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import (
    ceil_div,
    flatten_rows_view,
    is_cute_jit_enabled,
    warn_and_run_fallback,
)
from kestrel_kernels.swiglu.fallback import _gate_up_hidden, gated_activation_torch
from kestrel_kernels.swiglu.variants import (
    GATED_ACTIVATION_CONFIG_BY_KEY,
    GATED_ACTIVATION_CONFIGS,
    gated_activation_variant_key,
)

_family = CubinFamily("swiglu")
_ENABLE_JIT = is_cute_jit_enabled()

_ELEMS_PER_BLOCK = 128 * 8

if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


def _compile_variant(variant_key: str):
    activation, layout, hidden = GATED_ACTIVATION_CONFIG_BY_KEY[variant_key]
    return _cubin_bundles._compile_gated_activation(
        hidden=hidden,
        activation=activation,
        layout=layout,
    )


def _ensure_variant(variant_key: str, gate_up: torch.Tensor) -> bool:
    device_index = int(gate_up.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if _family.is_available(variant_key):
        return True
    if not _ENABLE_JIT:
        return False
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_compile_variant(variant_key),
        block_x=128,
        device_index=device_index,
    )
    return True


def _is_aligned(tensor: torch.Tensor, alignment: int = 16) -> bool:
    return tensor.data_ptr() % alignment == 0


def gated_activation_into(
    out: torch.Tensor,
    gate_up: torch.Tensor,
    *,
    activation: str,
    layout: str,
) -> None:
    hidden = _gate_up_hidden(gate_up, layout)
    expected_shape = (*gate_up.shape[:-1], hidden)
    if out.shape != expected_shape:
        raise ValueError(
            f"out shape must be {expected_shape}, got {tuple(out.shape)}"
        )
    if gate_up.numel() == 0:
        return
    if torch.compiler.is_compiling():
        gated_activation_torch(
            gate_up,
            activation=activation,
            layout=layout,
            out=out,
        )
        return

    config = (activation, layout, hidden)
    variant_key = gated_activation_variant_key(*config)
    supported = (
        config in GATED_ACTIVATION_CONFIGS
        and gate_up.is_cuda
        and out.is_cuda
        and gate_up.dtype == torch.bfloat16
        and out.dtype == torch.bfloat16
        and gate_up.stride(-1) == 1
        and out.stride(-1) == 1
    )
    if supported:
        try:
            flat_gate_up = flatten_rows_view(gate_up)
            flat_out = flatten_rows_view(out)
        except ValueError:
            supported = False
        else:
            supported = (
                _is_aligned(flat_gate_up)
                and _is_aligned(flat_out)
                and int(flat_gate_up.stride(0)) % 8 == 0
                and int(flat_out.stride(0)) % 8 == 0
                and _ensure_variant(variant_key, gate_up)
            )

    if supported:
        grid_y = ceil_div(hidden, _ELEMS_PER_BLOCK)
        dispatch = _family.resolve_dispatch(
            flat_gate_up,
            variant_key=variant_key,
            grid_x=flat_gate_up.shape[0],
            grid_y=grid_y,
        )
        dispatch(flat_out, flat_gate_up)
        return

    warn_and_run_fallback(
        kernel_key=f"gated_activation:{activation}:{layout}",
        message=(
            "kestrel-kernels: no native gated activation variant for "
            f"activation={activation!r} layout={layout!r} "
            f"gate_up={tuple(gate_up.shape)} dtype={gate_up.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=gated_activation_torch,
        kwargs={
            "gate_up": gate_up,
            "activation": activation,
            "layout": layout,
            "out": out,
        },
    )


__all__ = [
    "gated_activation_into",
]
